import{authMessage}from'./auth-errors.js';import{ProjectWorkspace}from'./project-store.js';import{setSession,clearSession}from'./session.js';import'./style.css';import'./account.css';
const root=document.querySelector('#authRoot'),editor=document.querySelector('#app');let cloud,mode='login',activeUid=null,sessionToken=0,loaded=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function frame(content){root.innerHTML=`<div class="auth-shell"><section class="auth-story"><a class="auth-brand" href="${import.meta.env.BASE_URL}"><span>≈</span> Liêm RAS <span>Studio</span></a><div><p class="auth-eyebrow">KHÔNG GIAN THIẾT KẾ CỦA BẠN</p><h1>Mỗi ý tưởng.<br>Một hệ RAS riêng.</h1><p>Từ bản vẽ đầu tiên đến hệ thống hoàn chỉnh.<br>Thiết kế, tính toán và lưu các mô hình tại một nơi.</p><div class="auth-illustration"><div class="auth-tank"></div><div class="auth-pipes"></div><div class="auth-filter f1"></div><div class="auth-filter f2"></div><div class="auth-filter f3"></div></div></div><small>2D & 3D · Tài khoản riêng · Nhiều mô hình RAS</small></section><section class="auth-panel">${content}</section></div>`;}
function showAuth(message=''){
 const local=cloud.mode==='local',title=mode==='register'?'Tạo không gian của bạn':mode==='reset'?'Đặt lại mật khẩu':'Đăng nhập để thiết kế';
 const intro=mode==='reset'?'Nhập email tài khoản để nhận hướng dẫn đặt lại mật khẩu.':local?'Tài khoản trên trình duyệt này. Mô hình được mã hóa bằng mật khẩu, không đồng bộ giữa các máy.':'Dùng email làm tên đăng nhập. Mỗi tài khoản có thư viện mô hình riêng.';
 const tabs=mode!=='reset'?`<div class="auth-tabs"><button data-mode="login" class="${mode==='login'?'active':''}">Đăng nhập</button><button data-mode="register" class="${mode==='register'?'active':''}">Đăng ký</button></div>`:'';
 const remember=!local?'<label><input name="remember" type="checkbox"> Giữ đăng nhập trên máy này</label><button type="button" id="forgotPassword">Quên mật khẩu?</button>':'<span>Chỉ kết thúc phiên khi tải lại trang; tài khoản vẫn được giữ.</span>';
 const loginOptions=mode==='login'?`<div class="auth-options">${remember}</div>`:'';
 const confirm=mode==='register'?'<label>Nhập lại mật khẩu<input name="confirmPassword" type="password" autocomplete="new-password" minlength="8" maxlength="128" required placeholder="Nhập lại mật khẩu"></label>':'';
 const password=mode!=='reset'?`<label>Mật khẩu<input name="password" type="password" autocomplete="${mode==='register'?'new-password':'current-password'}" ${mode==='register'?'minlength="8"':''} maxlength="128" required placeholder="${mode==='register'?'Ít nhất 8 ký tự':'Nhập mật khẩu'}"></label>${confirm}${loginOptions}`:'';
 const footnote=local?'Lưu trên máy: IndexedDB · AES-GCM + PBKDF2.<br>Không có khôi phục mật khẩu. Xóa dữ liệu trình duyệt sẽ xóa mô hình cục bộ.':'Firebase Authentication & Firestore.<br>Mô hình chỉ hiển thị cho tài khoản sở hữu.';
 editor.hidden=true;root.hidden=false;frame(`<div class="auth-form-wrap"><div class="eyebrow">CHÀO MỪNG ĐẾN LIÊM RAS STUDIO</div><h2>${title}</h2><p class="auth-intro">${intro}</p><div class="auth-provider">${local?'◉ Lưu mã hóa trên máy này':'◉ Đồng bộ Firebase'}</div>${local?'<div id="localStorageInfo" class="auth-storage-info" role="status">Đang kiểm tra dữ liệu trên trình duyệt này…</div>':''}${tabs}<form id="authForm">${mode==='register'?'<label>Họ tên / tên hiển thị<input name="displayName" maxlength="80" autocomplete="name" placeholder="Tên của bạn" required></label>':''}<label>${local?'Tên đăng nhập hoặc email':'Email / tên đăng nhập'}<input name="email" type="${local?'text':'email'}" autocomplete="username" placeholder="${local?'ten_dang_nhap':'ban@example.com'}" required maxlength="254"></label>${password}<p id="authMessage" class="auth-message" role="status">${esc(message)}</p><button class="primary auth-submit" type="submit">${mode==='register'?'Tạo tài khoản':mode==='reset'?'Gửi hướng dẫn':'Đăng nhập'} <span>→</span></button></form>${mode==='reset'?'<button class="auth-back" data-mode="login">← Quay lại đăng nhập</button>':''}<div class="auth-footnote">${footnote}<br><button id="switchBackend" class="auth-back">${local?'Muốn đồng bộ? Dùng Firebase →':'Dùng tài khoản lưu trên máy này →'}</button></div></div>`);
 if(local){const info=root.querySelector('#localStorageInfo');cloud.storageInfo?.().then(async stats=>{const persistent=await navigator.storage?.persisted?.();if(!info.isConnected)return;info.textContent=`${stats.accounts?'Tìm thấy '+stats.accounts+' tài khoản đã lưu.':'Chưa thấy tài khoản cục bộ trên trình duyệt này.'} Cập nhật web không xóa tài khoản. Địa chỉ: ${location.origin}. ${persistent?'Dữ liệu được trình duyệt bảo vệ lưu trữ.':'Dữ liệu có thể bị xóa khi dọn trình duyệt hoặc dùng chế độ riêng tư.'}`;if(navigator.storage?.persist){const b=document.createElement('button');b.type='button';b.textContent='Yêu cầu giữ dữ liệu trên máy';b.onclick=async()=>{const ok=await navigator.storage.persist();b.textContent=ok?'Đã được trình duyệt cho phép':'Trình duyệt chưa cấp; hãy sao lưu mã hóa';b.disabled=true;};info.append(document.createElement('br'),b);}}).catch(()=>{if(info.isConnected)info.textContent='Không kiểm tra được dữ liệu lưu trên trình duyệt. Không xóa dữ liệu trang khi đang tìm tài khoản cũ.';});try{root.querySelector('[name="email"]').value=localStorage.getItem('ras-last-local-login')||'';}catch{}const restore=document.createElement('button');restore.className='auth-back';restore.textContent='Khôi phục tài khoản từ bản sao lưu mã hóa';restore.onclick=()=>showRestore();root.querySelector('.auth-footnote').append(document.createElement('br'),restore);}
 root.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;showAuth();});const forgot=root.querySelector('#forgotPassword');if(forgot)forgot.onclick=()=>{mode='reset';showAuth();};root.querySelector('#authForm').onsubmit=submitAuth;
 root.querySelector('#switchBackend').onclick=async()=>{if(local){try{const r=await fetch(`${import.meta.env.BASE_URL}firebase-config.json`,{cache:'no-store'}),cfg=await r.json();if(!cfg.projectId||!cfg.apiKey||!cfg.appId){showAuth('Firebase chưa được quản trị viên cấu hình. Bạn vẫn có thể dùng tài khoản mã hóa trên máy.');return;}localStorage.setItem('ras-backend-choice','firebase');location.reload();}catch{showAuth('Chưa kết nối được Firebase. Hãy thử lại sau.');}}else{localStorage.setItem('ras-backend-choice','local');location.reload();}};
}
async function submitAuth(e){e.preventDefault();const form=e.currentTarget,button=form.querySelector('[type="submit"]'),data=new FormData(form),email=String(data.get('email')||'').trim(),password=String(data.get('password')||'');if(mode==='register'&&password!==data.get('confirmPassword')){document.querySelector('#authMessage').textContent='Hai mật khẩu chưa trùng khớp.';return;}button.disabled=true;document.querySelector('#authMessage').textContent='Đang xử lý…';try{if(mode==='reset'){await cloud.reset(email);showAuth('Nếu email có tài khoản, bạn sẽ nhận được hướng dẫn đặt lại mật khẩu.');}else if(mode==='register')await cloud.register(email,password,String(data.get('displayName')||'').trim());else await cloud.login(email,password,data.get('remember')==='on');if(cloud.mode==='local'&&mode!=='reset')try{localStorage.setItem('ras-last-local-login',email);}catch{}}catch(error){if(document.querySelector('#authMessage'))document.querySelector('#authMessage').textContent=authMessage(error);}finally{if(button.isConnected)button.disabled=false;}}
function loading(text){root.hidden=false;editor.hidden=true;frame(`<div class="auth-form-wrap"><div class="auth-spinner"></div><h2>${text}</h2><p class="auth-intro">Đang mở không gian mô hình của bạn.</p></div>`);}
function setupError(error){root.hidden=false;editor.hidden=true;frame(`<div class="auth-form-wrap"><div class="eyebrow">CHƯA MỞ ĐƯỢC NƠI LƯU MÔ HÌNH</div><h2>Kiểm tra kết nối và trình duyệt</h2><p class="auth-intro">${error?.code==='local/unavailable'?esc(error.message):'Chưa tải được tài khoản hoặc mô hình. Hãy kiểm tra mạng, quyền lưu dữ liệu trình duyệt và cấu hình dịch vụ.'}</p><p class="auth-message" role="alert">Trình thiết kế chỉ mở sau khi xác thực.</p><button class="primary" id="retryCloud">Thử lại</button></div>`);document.querySelector('#retryCloud').onclick=()=>location.reload();const localButton=document.createElement('button');localButton.textContent='Dùng dữ liệu cục bộ trên trình duyệt này';localButton.className='auth-back';localButton.onclick=()=>{localStorage.setItem('ras-backend-choice','local');location.reload();};document.querySelector('.auth-form-wrap').append(localButton);}
async function chooseBackend(){
 if(import.meta.env.DEV&&import.meta.env.VITE_QA_PREVIEW==='true'){const{connectPreview}=await import('./dev-preview.js');return connectPreview();}
 const preference=localStorage.getItem('ras-backend-choice');
 if(preference==='firebase'){const{connectCloud}=await import('./cloud.js');return connectCloud();}
 const{connectLocal}=await import('./local-backend.js');const local=await connectLocal(),pin=mode=>{try{localStorage.setItem('ras-backend-choice',mode);}catch{}};
 if(preference==='local'||(await local.storageInfo()).accounts>0){pin('local');return local;}
 let config={};try{const response=await fetch(`${import.meta.env.BASE_URL}firebase-config.json`,{cache:'no-store'});if(response.ok)config=await response.json();}catch{}
 if(config.apiKey&&config.projectId&&config.appId&&config.authDomain){local.close();pin('firebase');const{connectCloud}=await import('./cloud.js');return connectCloud();}
 pin('local');return local;
}
function showRestore(){frame(`<div class="auth-form-wrap"><h2>Khôi phục tài khoản</h2><p class="auth-intro">Chọn bản sao lưu mã hóa và nhập mật khẩu gốc. Không ghi đè tài khoản/mô hình hiện có. Đây là dữ liệu trên trình duyệt đang mở, không phải Firebase.</p><form id="restoreAccount"><label>Bản sao lưu<input name="backup" type="file" accept=".rasvault,.json" required></label><label>Mật khẩu gốc<input name="password" type="password" autocomplete="current-password" required></label><p class="auth-message" role="status" id="restoreMessage"></p><button class="primary">Khôi phục</button></form><button class="auth-back" id="restoreBack">Quay lại đăng nhập</button></div>`);root.querySelector('#restoreBack').onclick=()=>showAuth();root.querySelector('#restoreAccount').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,b=form.querySelector('button');b.disabled=true;try{const file=form.elements.backup.files[0];if(file.size>20e6)throw Error('Bản sao lưu tối đa 20 MB.');const login=await cloud.restoreBackup(await file.text(),form.elements.password.value);try{localStorage.setItem('ras-last-local-login',login);}catch{}mode='login';showAuth('Đã khôi phục tài khoản và mô hình. Đăng nhập bằng mật khẩu gốc.');}catch(error){root.querySelector('#restoreMessage').textContent=error.code?authMessage(error):error.message;}finally{if(b.isConnected)b.disabled=false;}};}
loading('Đang mở Liêm RAS Studio');
(async()=>{try{cloud=await chooseBackend();cloud.watch(async user=>{const token=++sessionToken;if(activeUid&&user?.uid!==activeUid){editor.hidden=true;root.hidden=false;document.querySelectorAll('dialog[open]').forEach(d=>d.close());clearSession();location.reload();return;}if(!user){clearSession();activeUid=null;mode='login';showAuth();return;}activeUid=user.uid;loading('Đang tải các mô hình RAS');try{const workspace=new ProjectWorkspace(cloud.repo,user.uid,detail=>window.dispatchEvent(new CustomEvent('ras-save-status',{detail})));await workspace.start();if(token!==sessionToken){workspace.close();return;}setSession({cloud,workspace,user});if(!loaded){await import('./app.js');loaded=true;}if(token!==sessionToken)return;editor.hidden=false;root.hidden=true;}catch(error){if(token!==sessionToken)return;setupError(error);const signout=document.createElement('button');signout.textContent='Đăng xuất';signout.style.marginLeft='10px';signout.onclick=()=>cloud.logout();document.querySelector('.auth-form-wrap').append(signout);}});}catch(error){setupError(error);}})();
